/* ── Reset & Base ─────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #ffffff;
  --color-surface:     #f7f7f5;
  --color-surface-2:   #efefed;
  --color-border:      #e2e2de;
  --color-text:        #111110;
  --color-text-muted:  #6b6b68;
  --color-accent:      #1a1a18;
  --color-accent-inv:  #ffffff;
  --color-deal:        #c0392b;
  --color-deal-bg:     #fff5f5;
  --color-tag:         #e8f4fd;
  --color-tag-text:    #1a6fa8;
  --radius-sm:         6px;
  --radius-md:         12px;
  --radius-lg:         20px;
  --shadow-card:       0 2px 12px rgba(0,0,0,.07), 0 1px 3px rgba(0,0,0,.05);
  --shadow-hover:      0 8px 28px rgba(0,0,0,.12), 0 2px 6px rgba(0,0,0,.07);
  --font-sans:         'Inter', system-ui, -apple-system, sans-serif;
  --transition:        0.22s cubic-bezier(.4,0,.2,1);
  --max-width:         1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
ul { list-style: none; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Skip Link ────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--color-accent);
  color: var(--color-accent-inv);
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 14px;
  z-index: 1000;
  transition: top var(--transition);
}
.skip-link:focus { top: 16px; }

/* ── Topbar ───────────────────────────────────────── */
.topbar {
  background: var(--color-accent);
  color: var(--color-accent-inv);
  text-align: center;
  padding: 9px 24px;
  font-size: 13px;
  letter-spacing: .02em;
}
.topbar strong { font-weight: 600; }

/* ── Header ───────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.96);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 66px;
}

/* Logo */
.site-logo {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-text);
  white-space: nowrap;
  flex-shrink: 0;
}
.site-logo span { color: #c0392b; }

/* Primary nav */
.primary-nav { display: flex; gap: 4px; flex: 1; }
.primary-nav a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: background var(--transition), color var(--transition);
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  background: var(--color-surface);
  color: var(--color-text);
}

/* Search */
.search-form {
  display: flex;
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 999px;
  padding: 0 14px;
  gap: 8px;
  height: 40px;
  width: 240px;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.search-form:focus-within {
  border-color: var(--color-text);
  box-shadow: 0 0 0 3px rgba(0,0,0,.08);
}
.search-form input {
  border: none;
  background: transparent;
  font-size: 14px;
  font-family: var(--font-sans);
  color: var(--color-text);
  flex: 1;
  outline: none;
}
.search-form input::placeholder { color: var(--color-text-muted); }
.search-form button {
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
}

/* Header actions */
.header-actions { display: flex; align-items: center; gap: 4px; }
.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text);
  transition: background var(--transition);
  position: relative;
}
.icon-btn:hover { background: var(--color-surface); }
.icon-btn:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
}
.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  background: var(--color-deal);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  width: 16px;
  height: 16px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ── Hero ─────────────────────────────────────────── */
.hero {
  background: #0f0f0e;
  color: #fff;
  overflow: hidden;
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: center;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 80% at 75% 50%, #1e3a5f 0%, transparent 65%),
    radial-gradient(ellipse 50% 60% at 20% 80%, #3d1a2e 0%, transparent 60%);
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 80px 0;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: rgba(255,255,255,.6);
  margin-bottom: 20px;
}
.hero-eyebrow::before {
  content: '';
  width: 24px;
  height: 2px;
  background: rgba(255,255,255,.4);
  border-radius: 1px;
}
.hero-title {
  font-size: clamp(36px, 5vw, 64px);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -.03em;
  margin-bottom: 20px;
}
.hero-title em {
  font-style: normal;
  background: linear-gradient(135deg, #74b9e0 0%, #a29bfe 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-desc {
  font-size: 17px;
  color: rgba(255,255,255,.65);
  max-width: 480px;
  margin-bottom: 36px;
  line-height: 1.7;
}
.hero-cta-group { display: flex; gap: 12px; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: #0f0f0e;
  font-size: 15px;
  font-weight: 700;
  padding: 14px 28px;
  border-radius: 999px;
  border: none;
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition);
  letter-spacing: -.01em;
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(255,255,255,.2);
}
.btn-primary:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 3px;
}
.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,.1);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  padding: 14px 28px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.2);
  cursor: pointer;
  transition: background var(--transition);
  letter-spacing: -.01em;
}
.btn-secondary:hover { background: rgba(255,255,255,.18); }
.btn-secondary:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 3px;
}
.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.hero-product-card {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-lg);
  padding: 32px;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  max-width: 340px;
  width: 100%;
}
.hero-product-img {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  background: rgba(255,255,255,.06);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
}
.hero-product-meta { color: rgba(255,255,255,.5); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; margin-bottom: 6px; }
.hero-product-name { font-size: 18px; font-weight: 700; margin-bottom: 4px; }
.hero-product-price { font-size: 22px; font-weight: 800; color: rgba(255,255,255,.9); }
.hero-floating-badge {
  position: absolute;
  top: -16px;
  right: -16px;
  background: var(--color-deal);
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  padding: 8px 14px;
  border-radius: 999px;
  box-shadow: 0 4px 16px rgba(192,57,43,.4);
  letter-spacing: .02em;
}
.hero-stats {
  display: flex;
  gap: 20px;
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,.1);
}
.hero-stat-num { font-size: 20px; font-weight: 800; }
.hero-stat-label { font-size: 11px; color: rgba(255,255,255,.45); text-transform: uppercase; letter-spacing: .08em; }

/* ── Section Shared ───────────────────────────────── */
.section { padding: 72px 0; }
.section--alt { background: var(--color-surface); }
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 40px;
}
.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: 6px;
}
.section-title {
  font-size: clamp(24px, 3vw, 34px);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.1;
}
.section-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-muted);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  transition: color var(--transition);
  flex-shrink: 0;
}
.section-link:hover { color: var(--color-text); }
.section-link:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Category Chips ───────────────────────────────── */
.category-strip { padding: 28px 0; border-bottom: 1px solid var(--color-border); }
.category-list {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: none;
}
.category-list::-webkit-scrollbar { display: none; }
.category-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
  color: var(--color-text);
}
.category-chip:hover {
  background: var(--color-surface-2);
  border-color: var(--color-text);
  transform: translateY(-1px);
}
.category-chip:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
}
.category-chip.active {
  background: var(--color-text);
  border-color: var(--color-text);
  color: #fff;
}
.chip-icon { font-size: 16px; line-height: 1; }

/* ── Product Card ─────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-3px);
}

.product-img-wrap {
  position: relative;
  background: var(--color-surface);
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  overflow: hidden;
}
.product-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 9px;
  border-radius: 999px;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge--new { background: var(--color-text); color: #fff; }
.badge--sale { background: var(--color-deal); color: #fff; }
.badge--bestseller { background: #f39c12; color: #fff; }

.product-wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: rgba(255,255,255,.9);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 16px;
  opacity: 0;
  transition: opacity var(--transition), background var(--transition);
}
.product-card:hover .product-wishlist,
.product-wishlist:focus-visible { opacity: 1; }
.product-wishlist:hover { background: #fff; }
.product-wishlist:focus-visible {
  opacity: 1;
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
}
.product-wishlist.active { color: var(--color-deal); }

.product-body { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.product-category { font-size: 11px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--color-text-muted); margin-bottom: 4px; }
.product-name {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--color-text);
  margin-bottom: 8px;
  flex: 1;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 10px;
}
.stars { color: #f39c12; font-size: 12px; letter-spacing: 1px; }
.rating-count { font-size: 12px; color: var(--color-text-muted); }
.product-price-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}
.price-current { font-size: 18px; font-weight: 800; }
.price-original {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.price-save {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-deal);
  background: var(--color-deal-bg);
  padding: 2px 7px;
  border-radius: 999px;
}
.product-add-btn {
  width: 100%;
  padding: 11px;
  background: var(--color-text);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
  font-family: var(--font-sans);
  letter-spacing: -.01em;
}
.product-add-btn:hover { background: #333; }
.product-add-btn:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
}
.product-add-btn:active { transform: scale(.98); }

/* ── Deals Section ────────────────────────────────── */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.deal-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  aspect-ratio: 4/3;
  display: flex;
  align-items: flex-end;
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition);
}
.deal-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-hover);
}
.deal-card:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 3px;
  border-radius: var(--radius-md);
}
.deal-card-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  transition: transform var(--transition);
}
.deal-card:hover .deal-card-bg { transform: scale(1.05); }
.deal-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.7) 0%, rgba(0,0,0,.1) 60%, transparent 100%);
}
.deal-card-body {
  position: relative;
  padding: 20px;
  color: #fff;
  width: 100%;
}
.deal-discount {
  display: inline-block;
  background: var(--color-deal);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 999px;
  margin-bottom: 8px;
  letter-spacing: .04em;
}
.deal-card-title { font-size: 18px; font-weight: 700; line-height: 1.2; margin-bottom: 4px; }
.deal-card-sub { font-size: 13px; color: rgba(255,255,255,.7); }

.deal-card--large {
  grid-column: span 2;
  aspect-ratio: 16/9;
}
.deal-card--large .deal-card-bg { font-size: 120px; }
.deal-card--large .deal-card-title { font-size: 26px; }

/* ── Timer ────────────────────────────────────────── */
.timer-section {
  background: var(--color-text);
  color: #fff;
  padding: 40px 0;
}
.timer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.timer-text h2 { font-size: 22px; font-weight: 800; letter-spacing: -.03em; margin-bottom: 4px; }
.timer-text p { font-size: 14px; color: rgba(255,255,255,.6); }
.countdown {
  display: flex;
  gap: 12px;
  align-items: center;
}
.countdown-unit {
  text-align: center;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  min-width: 66px;
}
.countdown-num {
  font-size: 28px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: -.02em;
  line-height: 1;
  display: block;
}
.countdown-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.5);
  margin-top: 4px;
  display: block;
}
.countdown-sep { font-size: 24px; font-weight: 800; opacity: .4; align-self: center; margin-bottom: 10px; }
.btn-timer {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: var(--color-text);
  font-size: 15px;
  font-weight: 700;
  padding: 14px 26px;
  border-radius: 999px;
  border: none;
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition);
  font-family: var(--font-sans);
  white-space: nowrap;
}
.btn-timer:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255,255,255,.2);
}
.btn-timer:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 3px;
}

/* ── Editorial ────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.editorial-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.editorial-card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-3px);
}
.editorial-img {
  aspect-ratio: 16/10;
  background: var(--color-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 52px;
  overflow: hidden;
  transition: transform var(--transition);
}
.editorial-card:hover .editorial-img { transform: scale(1.03); }
.editorial-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.editorial-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-tag-text);
  background: var(--color-tag);
  padding: 4px 10px;
  border-radius: 999px;
  margin-bottom: 12px;
  width: fit-content;
}
.editorial-title {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 8px;
  letter-spacing: -.01em;
  color: var(--color-text);
}
.editorial-excerpt {
  font-size: 14px;
  color: var(--color-text-muted);
  line-height: 1.6;
  flex: 1;
  margin-bottom: 16px;
}
.editorial-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  color: var(--color-text-muted);
  padding-top: 14px;
  border-top: 1px solid var(--color-border);
  margin-top: auto;
}
.editorial-author { display: flex; align-items: center; gap: 8px; }
.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: var(--color-surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.editorial-read-link {
  font-weight: 600;
  color: var(--color-text);
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}
.editorial-card:hover .editorial-read-link { gap: 8px; }
.editorial-read-link:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Brands ───────────────────────────────────────── */
.brands-section {
  padding: 48px 0;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}
.brands-label {
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: 28px;
}
.brand-list {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;
}
.brand-item {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-surface-2);
  transition: color var(--transition);
  cursor: pointer;
  filter: grayscale(1) opacity(.5);
  transition: filter var(--transition);
}
.brand-item:hover { filter: grayscale(0) opacity(1); }

/* ── Newsletter ───────────────────────────────────── */
.newsletter {
  background: var(--color-surface);
  padding: 72px 0;
  text-align: center;
}
.newsletter-inner { max-width: 540px; margin: 0 auto; }
.newsletter-icon { font-size: 40px; margin-bottom: 16px; }
.newsletter-title { font-size: 28px; font-weight: 800; letter-spacing: -.03em; margin-bottom: 10px; }
.newsletter-desc { font-size: 15px; color: var(--color-text-muted); margin-bottom: 28px; }
.newsletter-form {
  display: flex;
  gap: 10px;
  max-width: 440px;
  margin: 0 auto 14px;
}
.newsletter-input {
  flex: 1;
  padding: 13px 18px;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  font-size: 14px;
  font-family: var(--font-sans);
  background: #fff;
  color: var(--color-text);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.newsletter-input:focus {
  border-color: var(--color-text);
  box-shadow: 0 0 0 3px rgba(0,0,0,.07);
}
.newsletter-submit {
  padding: 13px 22px;
  background: var(--color-text);
  color: #fff;
  border: none;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  font-family: var(--font-sans);
  white-space: nowrap;
  transition: background var(--transition);
}
.newsletter-submit:hover { background: #333; }
.newsletter-submit:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 3px;
}
.newsletter-disclaimer { font-size: 12px; color: var(--color-text-muted); }

/* ── Footer ───────────────────────────────────────── */
.site-footer {
  background: #0f0f0e;
  color: rgba(255,255,255,.7);
  padding: 60px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .site-logo { color: #fff; margin-bottom: 14px; font-size: 20px; }
.footer-brand p { font-size: 14px; line-height: 1.7; max-width: 260px; }
.footer-social { display: flex; gap: 10px; margin-top: 20px; }
.social-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  cursor: pointer;
  transition: background var(--transition);
  color: #fff;
  text-decoration: none;
}
.social-btn:hover { background: rgba(255,255,255,.16); }
.social-btn:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}
.footer-col h3 {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 16px;
}
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col a {
  font-size: 14px;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.footer-col a:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
  border-radius: 3px;
}
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-top: 28px;
  border-top: 1px solid rgba(255,255,255,.08);
  font-size: 13px;
  flex-wrap: wrap;
}
.footer-bottom-links { display: flex; gap: 20px; }
.footer-bottom-links a {
  color: rgba(255,255,255,.4);
  transition: color var(--transition);
}
.footer-bottom-links a:hover { color: rgba(255,255,255,.8); }
.footer-payment { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.payment-badge {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 5px;
  padding: 4px 8px;
  font-size: 11px;
  font-weight: 600;
  color: rgba(255,255,255,.6);
  letter-spacing: .04em;
}

/* ── Toast ────────────────────────────────────────── */
#toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background: var(--color-text);
  color: #fff;
  padding: 14px 20px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 600;
  box-shadow: 0 8px 32px rgba(0,0,0,.25);
  display: flex;
  align-items: center;
  gap: 10px;
  transform: translateY(80px);
  opacity: 0;
  transition: transform .3s cubic-bezier(.34,1.56,.64,1), opacity .3s ease;
  pointer-events: none;
  z-index: 999;
  max-width: 320px;
}
#toast.visible {
  transform: translateY(0);
  opacity: 1;
}

/* ── Responsive ───────────────────────────────────── */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--large { grid-column: span 2; }
}

@media (max-width: 768px) {
  .primary-nav { display: none; }
  .search-form { display: none; }
  .menu-toggle { display: flex; }

  .hero-inner { grid-template-columns: 1fr; text-align: center; }
  .hero-cta-group { justify-content: center; }
  .hero-desc { margin: 0 auto 36px; }
  .hero-visual { display: none; }

  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--large { grid-column: span 1; }

  .editorial-grid { grid-template-columns: 1fr; }

  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }

  .timer-inner { flex-direction: column; align-items: flex-start; }

  .newsletter-form { flex-direction: column; border-radius: var(--radius-md); }
  .newsletter-input,
  .newsletter-submit { border-radius: var(--radius-sm); }

  .section-header { flex-direction: column; align-items: flex-start; }

  .brand-list { gap: 24px; }
}

@media (max-width: 480px) {
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .product-add-btn { font-size: 12px; padding: 10px; }
  .countdown { gap: 6px; }
  .countdown-unit { min-width: 54px; padding: 10px 12px; }
  .countdown-num { font-size: 22px; }
}

/* ── Focus visible global ─────────────────────────── */
:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
}

