*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #ffffff;
  --color-surface:     #f7f7f5;
  --color-surface-2:   #efefed;
  --color-border:      #e2e2de;
  --color-text:        #111110;
  --color-text-muted:  #6b6b68;
  --color-accent:      #1a1a18;
  --color-accent-inv:  #ffffff;
  --color-deal:        #c0392b;
  --color-deal-bg:     #fff5f5;
  --color-tag:         #e8f4fd;
  --color-tag-text:    #1a6fa8;
  --radius-sm:         6px;
  --radius-md:         12px;
  --radius-lg:         20px;
  --shadow-card:       0 2px 12px rgba(0,0,0,.07), 0 1px 3px rgba(0,0,0,.05);
  --shadow-hover:      0 8px 28px rgba(0,0,0,.12), 0 2px 6px rgba(0,0,0,.07);
  --font-sans:         'Inter', system-ui, -apple-system, sans-serif;
  --transition:        0.22s cubic-bezier(.4,0,.2,1);
  --max-width:         1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
ul { list-style: none; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Skip Link ────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--color-accent);
  color: var(--color-accent-inv);
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 14px;
  z-index: 1000;
  transition: top var(--transition);
}
.skip-link:focus { top: 16px; }

/* ── Topbar ───────────────────────────────────────── */
.topbar {
  background: var(--color-accent);
  color: var(--color-accent-inv);
  text-align: center;
  padding: 9px 24px;
  font-size: 13px;
  letter-spacing: .02em;
}
.topbar strong { font-weight: 600; }

/* ── Header ───────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.96);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 66px;
}

/* Logo */
.site-logo {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-text);
  white-space: nowrap;
  flex-shrink: 0;
}
.site-logo span { color: #c0392b; }

/* Primary nav */
.primary-nav { display: flex; gap: 4px; flex: 1; }
.primary-nav a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text-muted);
