  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ── Hero ─────────────────────────────────────────── */
.hero {
  background: #0f0f0e;
  color: #fff;
  overflow: hidden;
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: center;
