  --shadow-card:       0 2px 12px rgba(0,0,0,.07), 0 1px 3px rgba(0,0,0,.05);
  --shadow-hover:      0 8px 28px rgba(0,0,0,.12), 0 2px 6px rgba(0,0,0,.07);
  --font-sans:         'Inter', system-ui, -apple-system, sans-serif;
