  text-align: center;
  padding: 9px 24px;
  font-size: 13px;
  letter-spacing: .02em;
}
.topbar strong { font-weight: 600; }

/* ── Header ───────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.96);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 66px;
}

/* Logo */
.site-logo {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-text);
  white-space: nowrap;
  flex-shrink: 0;
}
.site-logo span { color: #c0392b; }

/* Primary nav */
.primary-nav { display: flex; gap: 4px; flex: 1; }
.primary-nav a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 15px;
