  height: 16px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ── Hero ─────────────────────────────────────────── */
.hero {
