  outline-offset: 2px;
}
.product-add-btn:active { transform: scale(.98); }

/* ── Deals Section ────────────────────────────────── */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.deal-card {
