  display: block;
}
.countdown-sep { font-size: 24px; font-weight: 800; opacity: .4; align-self: center; margin-bottom: 10px; }
.btn-timer {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: var(--color-text);
  font-size: 15px;
  font-weight: 700;
  padding: 14px 26px;
  border-radius: 999px;
  border: none;
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition);
  font-family: var(--font-sans);
  white-space: nowrap;
}
.btn-timer:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255,255,255,.2);
}
.btn-timer:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 3px;
