    { emoji: "🌿", bg: "linear-gradient(135deg,#1b4332,#2d6a4f)", title: "Eco Collection", sub: "Sustainable picks", discount: "Up to 30% off", large: false },
  ];

  container.innerHTML = deals.map(DealCard).join("");
}

function renderEditorial() {
  const container = document.getElementById("editorial-grid");
  if (!container) return;
  container.innerHTML = editorial.map(EditorialCard).join("");
}

/* ─── Cart Logic ─────────────────────────────────── */
function addToCart(id) {
  const product = products.find(p => p.id === id);
  if (!product) return;
  state.cart.push(product);
  state.cartCount++;
  updateCartBadge();
  showToast(`🛒 ${product.name} added to cart`);
}

function updateCartBadge() {
  const badge = document.getElementById("cart-badge");
  if (badge) {
    badge.textContent = state.cartCount;
    badge.setAttribute("aria-label", `${state.cartCount} items in cart`);
    badge.hidden = state.cartCount === 0;
  }
}

/* ─── Wishlist Logic ─────────────────────────────── */
function toggleWishlist(id, btn) {
  const product = products.find(p => p.id === id);
  if (!product) return;

  if (state.wishlist.has(id)) {
    state.wishlist.delete(id);
    btn.innerHTML = "♡";
    btn.classList.remove("active");
    btn.setAttribute("aria-pressed", "false");
    btn.setAttribute("aria-label", `Add to wishlist: ${product.name}`);
    showToast(`💔 Removed from wishlist`);
  } else {
    state.wishlist.add(id);
    btn.innerHTML = "♥";
    btn.classList.add("active");
    btn.setAttribute("aria-pressed", "true");
    btn.setAttribute("aria-label", `Remove from wishlist: ${product.name}`);
    showToast(`❤️ Added to wishlist`);
  }
}

/* ─── Toast ──────────────────────────────────────── */
let toastTimer = null;
function showToast(message) {
  const toast = document.getElementById("toast");
  if (!toast) return;
  toast.textContent = message;
  toast.classList.add("visible");
  toast.setAttribute("aria-live", "polite");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    toast.classList.remove("visible");
  }, 2800);
}

/* ─── Countdown Timer ────────────────────────────── */
function initCountdown() {
  const end = new Date();
  end.setHours(end.getHours() + 11, end.getMinutes() + 42, end.getSeconds() + 30);

  function tick() {
    const now = new Date();
    const diff = Math.max(0, end - now);

    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);

    const pad = n => String(n).padStart(2, "0");
    const setEl = (id, val, label) => {
      const el = document.getElementById(id);
      if (el) {
        el.textContent = pad(val);
        el.setAttribute("aria-label", `${val} ${label}`);
      }
    };

    setEl("cd-hours", h, "hours");
    setEl("cd-minutes", m, "minutes");
    setEl("cd-seconds", s, "seconds");

    if (diff > 0) requestAnimationFrame(tick);
  }

  requestAnimationFrame(tick);
}

/* ─── Category Filter ─────────────────────────────── */
function initCategoryFilter() {
  const chips = document.querySelectorAll(".category-chip");
  chips.forEach(chip => {
    chip.addEventListener("click", () => {
      chips.forEach(c => {
        c.classList.remove("active");
        c.setAttribute("aria-pressed", "false");
      });
      chip.classList.add("active");
      chip.setAttribute("aria-pressed", "true");

      const category = chip.dataset.category;
      const filtered = category === "all"
        ? products
        : products.filter(p => p.category.toLowerCase() === category.toLowerCase());

      const grid = document.getElementById("product-grid");
      if (grid) {
        grid.innerHTML = filtered.length
          ? filtered.map(ProductCard).join("")
          : `<p style="color:var(--color-text-muted);grid-column:1/-1;padding:24px 0;">No products in this category yet.</p>`;
      }
    });
  });
}

/* ─── Newsletter Form ────────────────────────────── */
function initNewsletter() {
  const form = document.getElementById("newsletter-form");
  if (!form) return;
  form.addEventListener("submit", e => {
    e.preventDefault();
    const input = form.querySelector("input[type='email']");
    if (input && input.value) {
      showToast("🎉 You're subscribed! Check your inbox.");
      input.value = "";
    }
  });
}

/* ─── Mobile Menu ────────────────────────────────── */
function initMobileMenu() {
  const toggle = document.getElementById("menu-toggle");
  const nav = document.getElementById("primary-nav");
  if (!toggle || !nav) return;

  toggle.addEventListener("click", () => {
    const open = nav.style.display === "flex";
    nav.style.display = open ? "" : "flex";
    nav.style.flexDirection = "column";
    nav.style.position = "absolute";
    nav.style.top = "66px";
    nav.style.left = "0";
    nav.style.right = "0";
    nav.style.background = "#fff";
    nav.style.padding = "12px 24px 20px";
    nav.style.borderBottom = "1px solid var(--color-border)";
    nav.style.gap = "4px";
    toggle.setAttribute("aria-expanded", String(!open));
    toggle.setAttribute("aria-label", open ? "Open menu" : "Close menu");
  });
}

/* ─── Init ───────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", () => {
  renderProducts();
  renderDeals();
  renderEditorial();
  initCountdown();
  initCategoryFilter();
  initNewsletter();
  initMobileMenu();
});
